Map<String, int> fn0(String logs) {
  final Map<String, int> counts = <String, int>{};
  final int n = logs.length;
  int i = 0;

  bool isDigit(String ch) =>
      ch.codeUnitAt(0) >= 0x30 && ch.codeUnitAt(0) <= 0x39;

  while (i < n) {
    if (logs[i] != '[') {
      i++;
      continue;
    }
    final int close = logs.indexOf(']', i);
    if (close < 0) break;
    final String name = logs.substring(i + 1, close);
    int j = close + 1;
    if (j < n && logs[j] == ':') j++;

    int total = 0;
    while (j < n && logs[j] != ';') {
      while (j < n && (logs[j] == ' ' || logs[j] == '\t')) j++;
      if (j >= n || logs[j] == ';') break;
      if (logs[j] == ',') {
        j++;
        continue;
      }

      bool hasContent = false;
      int mult = 1;

      if (logs[j] == '"') {
        hasContent = true;
        j++;
        while (j < n && logs[j] != '"') {
          if (logs[j] == '\\') j++;
          j++;
        }
        if (j < n) j++;
      } else {
        final int start = j;
        while (j < n &&
            logs[j] != ',' &&
            logs[j] != ';' &&
            logs[j] != '*') {
          j++;
        }
        hasContent = logs.substring(start, j).trim().isNotEmpty;
      }

      if (j < n && logs[j] == '*') {
        j++;
        final int start = j;
        while (j < n && isDigit(logs[j])) j++;
        final int? parsed = int.tryParse(logs.substring(start, j));
        if (parsed != null) mult = parsed;
      }

      if (hasContent) total += mult;

      while (j < n && logs[j] != ',' && logs[j] != ';') j++;
      if (j < n && logs[j] == ',') j++;
    }

    counts[name] = total;
    i = j;
    if (i < n && logs[i] == ';') i++;
  }

  return counts;
}

