List<String> fn0(List<int> requests) {
  final result = <String>[];

  for (final request in requests) {
    final floor = request.abs().toRadixString(8);
    if (request < 0) {
      result.add('Floor -$floor');
    } else {
      result.add('Floor $floor');
    }
  }

  return result;
}

int fn0(List<int> buckets) {
  int count = 0;
  for (final value in buckets) {
    if (value > 0 && (value & (value - 1)) == 0) {
      count++;
    }
  }
  return count;
}

