double fn0(List<String> log) {
  final stack = <int>[];
  for (final e in log) {
    if (e == '!') {
      if (stack.isNotEmpty) stack.removeLast();
    } else {
      final n = int.parse(e.substring(1));
      stack.add(e.codeUnitAt(0) == 0x55 ? n : -n);
    }
  }
  var sum = 0;
  for (final v in stack) {
    sum += v;
  }
  return sum / 2.0;
}

String fn0(List<int> moistureGrid) {
  if (moistureGrid.isEmpty) return '';
  if (moistureGrid.length == 1) return '${moistureGrid[0]}';
  final int mid = moistureGrid.length ~/ 2;
  final String left = fn0(moistureGrid.sublist(0, mid));
  final String right = fn0(moistureGrid.sublist(mid));
  return '($left|$right)';
}

List<T> fn0<T>(List<T> values, int count) {
  final result = <T>[];
  final end = values.length - count;
  for (var i = 0; i < end; i++) {
    result.add(values[i]);
  }
  return result;
}

