double fn0(String pixels) {
  if (pixels.isEmpty) {
    return 0.0;
  }

  final parts = pixels.split(' ');
  var sum = 0.0;

  for (var i = 0; i < parts.length; i += 2) {
    sum += int.parse(parts[i]) * double.parse(parts[i + 1]);
  }

  return sum;
}

