int fn0(String playlist, int threshold) {
  if (playlist.isEmpty) return 0;

  var total = 0;
  for (final token in playlist.split(' ')) {
    if (token.isEmpty) continue;

    final parts = token.split(':');
    if (parts.length != 2) continue;

    final key = int.parse(parts[0]);
    final value = int.parse(parts[1]);

    if (value > threshold) {
      total += key;
    }
  }

  return total;
}

