int fn0(String password) {
  int score = 0;
  for (int i = 0; i < password.length; i++) {
    final int c = password.codeUnitAt(i);
    if (c >= 48 && c <= 57) {
      score = (score * 11 + (c - 48)) % 97;
    }
  }
  return score;
}
